
package com.store.productservice.dto;
import java.math.BigDecimal;import java.time.LocalDateTime;
public class ProductResponse { private Long id; private String nom; private BigDecimal prix; private Integer quantite; private LocalDateTime dateCreation; public ProductResponse(){} public ProductResponse(Long id,String nom,BigDecimal prix,Integer quantite,LocalDateTime dateCreation){this.id=id;this.nom=nom;this.prix=prix;this.quantite=quantite;this.dateCreation=dateCreation;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getNom(){return nom;} public void setNom(String nom){this.nom=nom;} public BigDecimal getPrix(){return prix;} public void setPrix(BigDecimal prix){this.prix=prix;} public Integer getQuantite(){return quantite;} public void setQuantite(Integer quantite){this.quantite=quantite;} public LocalDateTime getDateCreation(){return dateCreation;} public void setDateCreation(LocalDateTime dateCreation){this.dateCreation=dateCreation;} }
